<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color Scheme Generator','description'=>'Generate a matching color scheme from a base color.','url'=>'https://smarttoolz.in/tools/color-scheme-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Color Scheme Generator</h1><p>Create five matching colors from a base color.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="c" type="color" value="#5b43ff"><button id="go" class="tool-btn">Generate Scheme</button><div id="o" style="display:flex;gap:8px;flex-wrap:wrap;margin-top:15px"></div></div></section></main><script>go.onclick=()=>{let h=c.value.replace('#',''),r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4),16),a=[];for(let i=0;i<5;i++){let f=i*.18;a.push(`rgb(${Math.round(r+(255-r)*f)},${Math.round(g+(255-g)*f)},${Math.round(b+(255-b)*f)})`)}o.innerHTML=a.map(x=>`<div style="padding:35px 15px;border-radius:10px;flex:1;min-width:80px;text-align:center">${x}</div>`).join('')}</script><?php smarttoolz_tool_page_end(); ?>